# Add helper function for name validation
def is_valid_function_name(name: str) -> bool:
    """Check if a string is a valid function name."""
    if not name or len(name) < 2:
        return False
    # Exclude common words and invalid patterns
    invalid = {"the", "a", "an", "if", "or", "and", "is", "in", "to", "of", "for"}
    if name.lower() in invalid:
        return False
    # Must start with letter or underscore
    if not (name[0].isalpha() or name[0] == "_"):
        return False
    return True
